-- Accepted editorial batch: 20 independently sourced public-domain song ideas.
WITH ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, sort_order) AS (
  VALUES
  ('Не смотри в зеркало','Изолированная художница видит мир только через экран, пока не решается выйти в город и прожить свою историю сама.','От первого лица, молодая художница.','Безопасная изоляция против права рискнуть реальной жизнью.','От тревоги к освобождению.','Она выходит из мастерской, сохранив свой голос.','Треснувшее зеркало становится знаком перемен.',ARRAY['Электропоп'],ARRAY['Тревога','Освобождение'],'Средняя',ARRAY['Поиск себя','Выбор','Город'],'Электропоп об художнице, которая перестаёт жить через экран и выходит в настоящий город.','Художница перестаёт смотреть на жизнь через экран и выходит в город сама.',111),
  ('Опоздал к рассвету','Девушка ждёт обещанного человека, а он всё переносит путь, пока не понимает цену собственного промедления.','От первого лица, ожидающая девушка.','Верность обещанию против привычки откладывать важное.','От надежды к светлой грусти.','Она закрывает дверь и выбирает идти дальше.','Закрывающаяся на рассвете дверь.',ARRAY['Баллада'],ARRAY['Светлая грусть'],'Низкая',ARRAY['Любовь','Ожидание'],'Баллада об ожидании человека, который слишком поздно учится не откладывать любовь.','Девушка перестаёт ждать человека, который всегда откладывал путь к ней.',112),
  ('Держи, пока меняет','Девушка остаётся рядом с любимым в самую тяжёлую ночь, когда давление извне будто меняет его до неузнаваемости.','От первого лица, девушка.','Верность близкому против страха его перемен.','От напряжения к решимости.','На рассвете они остаются вместе по собственному выбору.','Рука, которую нельзя разжать.',ARRAY['Фолк','Рок'],ARRAY['Решимость','Напряжение'],'Высокая',ARRAY['Любовь','Риск'],'Фолк-рок о девушке, которая удерживает любовь среди тяжёлых перемен.','Девушка не отпускает руку любимого, пока вокруг всё пытается их разлучить.',113),
  ('Задача для двоих','Двое влюблённых выдвигают друг другу невозможные условия и лишь затем понимают, что любовь не должна быть экзаменом.','От первого лица, девушка.','Желание проверить партнёра против равного разговора.','От иронии к взаимному уважению.','Они отменяют условия и начинают говорить честно.','Невозможная рубашка без швов.',ARRAY['Поп'],ARRAY['Ирония'],'Средняя',ARRAY['Любовь','Выбор'],'Ироничный поп о паре, которая меняет взаимные проверки на честный разговор.','Влюблённые перестают ставить друг другу невыполнимые условия.',114),
  ('Письмо с берега','Капитан получает приказ вывести корабль в опасный сезон и должен выбрать между служебным долгом и жизнью команды.','От первого лица, капитан.','Профессиональная ответственность против бездумного приказа.','От тревоги к твёрдости.','Он отказывается идти в шторм и принимает последствия.','Письмо с печатью на мокром берегу.',ARRAY['Рок'],ARRAY['Тревога','Смелость'],'Высокая',ARRAY['Море','Команда'],'Рок о капитане, который не ведёт команду в смертельный шторм ради чужого приказа.','Капитан читает приказ и выбирает жизнь команды, а не опасный рейс.',115),
  ('Луна проводит домой','Мать доверяет сыну важное ночное поручение и, потеряв его из вида, учится видеть не страх, а его самостоятельность.','От первого лица, мать.','Родительская тревога против доверия к ребёнку.','От паники к нежности.','Сын возвращается домой своим спокойным маршрутом.','Лунная дорога и медленный пони.',ARRAY['Фолк'],ARRAY['Нежность'],'Средняя',ARRAY['Семья','Дорога'],'Тёплый фолк о матери, которая учится доверять самостоятельности сына.','Мать ждёт ночью и понимает, что сын умеет находить свой путь домой.',116),
  ('Цена ответа','После тяжёлой ошибки герой должен понять, что уважение к чужой воле важнее его желания всё исправить одним жестом.','От первого лица, мужчина.','Искупление вины против привычки распоряжаться чужим выбором.','От вины к ответственности.','Он принимает отказ и начинает менять себя делами.','Вопрос, от которого зависит будущее.',ARRAY['Хип-хоп'],ARRAY['Вина','Освобождение'],'Средняя',ARRAY['Самоценность','Любовь'],'Хип-хоп об ответственности: герой учится уважать границы, а не требовать прощения.','Герой понимает, что честный ответ другого нельзя выторговать.',117),
  ('Долг записан','Город пользуется работой музыканта, а затем отказывается платить, пока он не превращает их обещание в песню, которую слышат все.','От первого лица, музыкант.','Данное слово против коллективного удобства.','От злости к силе.','Город признаёт долг перед тем, чьим трудом пользовался.','Мелодия, которую нельзя заглушить.',ARRAY['Панк'],ARRAY['Злость','Протест'],'Высокая',ARRAY['Работа','Город'],'Панк о музыканте, который требует оплату за честно выполненную работу.','Музыкант напоминает городу о долге песней, которую слышат все.',118),
  ('Вместо отца','Дочь берёт на себя семейную обязанность, скрывает себя ради отца и возвращается домой, чтобы жить уже под собственным именем.','От первого лица, дочь.','Долг перед семьёй против права не потерять себя.','От смелости к освобождению.','Она возвращается и сама рассказывает свою историю.','Доспех рядом с домашним зеркалом.',ARRAY['Эпик-рок'],ARRAY['Смелость','Сила'],'Высокая',ARRAY['Семья','Сила'],'Эпик-рок о дочери, которая защищает отца и возвращает себе собственный голос.','Дочь занимает место отца в опасном деле, а потом возвращается к себе.',119),
  ('Не отпускай разговор','Жена не соглашается с неизбежной утратой и проходит через трудный разговор, чтобы вернуть семье право на будущее.','От первого лица, жена.','Любовь и настойчивость против предрешённой потери.','От боли к надежде.','Семья встречает утро вместе.','Ночной путь, который не обрывается.',ARRAY['Соул'],ARRAY['Надежда','Нежность'],'Средняя',ARRAY['Любовь','Семья'],'Соул о женщине, которая не отпускает разговор, пока у семьи остаётся шанс на будущее.','Жена проходит через ночь рядом с любимым и возвращает семье надежду.',120),
  ('Счёт за свободу','Талантливая девушка принимает тяжёлое решение ради спасения семьи, но не отдаёт другим право распоряжаться её будущим.','От первого лица, девушка.','Семейный долг против личной свободы и достоинства.','От уязвимости к силе.','Она возвращает себе право выбирать следующий шаг.','Струна, которая остаётся своей в чужих руках.',ARRAY['R&B'],ARRAY['Уязвимость','Сила'],'Средняя',ARRAY['Семья','Самоценность'],'R&B о девушке, которая спасает семью, не отказываясь от права строить свою жизнь.','Девушка платит высокую цену за семью, но не отдаёт свою свободу навсегда.',121),
  ('Слова через пустыню','Двух влюблённых разлучают семьи и статус, но каждый сохраняет свой голос, чтобы любовь не превратилась в зависимость.','От первого лица, девушка.','Чужие запреты против права любить и оставаться собой.','От тоски к внутренней свободе.','Она выбирает жить и говорить от собственного имени.','Сообщение, идущее через пустыню.',ARRAY['Инди-поп'],ARRAY['Тоска','Свобода'],'Средняя',ARRAY['Любовь','Свобода'],'Инди-поп о любви на расстоянии, где оба сохраняют голос и достоинство.','Разлучённые влюблённые передают друг другу слова через пустыню запретов.',122),
  ('Имя без титула','Мужчина скрывает от любимой своё положение, надеясь быть выбранным без статуса, но тайна лишает её честного выбора.','От первого лица, женщина.','Доверие в любви против красивой лжи.','От растерянности к ясности.','Она требует правду прежде, чем говорить о будущем.','Письмо с настоящей фамилией.',ARRAY['Поп'],ARRAY['Меланхолия'],'Средняя',ARRAY['Любовь','Выбор'],'Поп о любви, в которой тайна о статусе оказывается важнее дорогих жестов.','Девушка узнаёт настоящее имя любимого и требует честности.',123),
  ('Мы оба не сказали','Два человека упускают взаимное чувство, потому что каждый заранее решает, какую жизнь другой обязан выбрать.','От первого лица, женщина.','Социальные ожидания против смелости сказать о чувствах.','От ностальгии к освобождению.','Спустя годы они перестают винить друг друга за молчание.','Фраза, не сказанная на развилке.',ARRAY['Синтвейв'],ARRAY['Ностальгия','Освобождение'],'Средняя',ARRAY['Любовь','Выбор'],'Синтвейв о двух людях, которые упустили любовь из-за взаимных предположений.','Двое понимают, что любовь исчезла не из-за судьбы, а из-за молчания.',124),
  ('Семейный выезд','Идеальный семейный праздник превращается в комический хаос, когда герой теряет контроль над поездкой и учится смеяться над собой.','От первого лица, отец.','Стремление всё контролировать против живого семейного дня.','От стыда к радости.','Дома историю превращают в любимую семейную легенду.','Шляпа, летящая за всадником.',ARRAY['Кантри'],ARRAY['Ирония','Радость'],'Высокая',ARRAY['Семья','Праздник'],'Кантри о семейной поездке, которая идёт не по плану, но становится лучшим воспоминанием.','Отец срывает семейный выезд и превращает его в самую смешную историю года.',125),
  ('Камни у порога','Отец отдаёт последнее, чтобы дать сыну шанс начать жизнь, но понимает: нельзя прожить выборы взрослого ребёнка вместо него.','От первого лица, отец.','Родительская жертва против невозможности контролировать судьбу сына.','От вины к тихому принятию.','Он оставляет недостроенную стену как знак открытой двери.','Камни у порога и незаконченная стена.',ARRAY['Баллада'],ARRAY['Вина','Светлая грусть'],'Низкая',ARRAY['Семья','Память'],'Баллада об отце, который отдаёт всё сыну и учится не жить его жизнь вместо него.','Отец строит стену для сына и учится принимать его собственные решения.',126),
  ('Дорога без карты','Катастрофа разлучает влюблённых, и годы поиска проверяют, способна ли любовь пережить исчезновение прежнего мира.','От первого лица, женщина.','Верность памяти против необходимости жить дальше.','От тоски к спокойной надежде.','Она находит не прошлое, а право продолжить путь.','Карта с единственной незачёркнутой дорогой.',ARRAY['Баллада'],ARRAY['Тоска','Надежда'],'Средняя',ARRAY['Любовь','Дорога'],'Баллада о долгом поиске после катастрофы и праве жить дальше.','Женщина много лет идёт по следу любви и находит в дороге собственную силу.',127),
  ('Берег, который выбрала','Женщина выбирает жизнь в мире людей, оставляя семью между двумя несовместимыми берегами и вынуждая близких принять её выбор.','От первого лица, отец.','Личная идентичность против близости семьи.','От боли к уважению чужого решения.','Он перестаёт звать её назад и заботится о детях.','Дети у воды смотрят на сухой берег.',ARRAY['Эмбиент'],ARRAY['Тоска','Уязвимость'],'Низкая',ARRAY['Семья','Выбор'],'Эмбиент о семье, которая учится уважать болезненный выбор близкого человека.','Отец перестаёт звать любимую назад и выбирает заботу о детях.',128),
  ('Ветер услышит','После неудачного похода герой оказывается далеко от дома, а его жена превращает ожидание в сильный голос, который зовёт его обратно.','От первого лица, жена.','Бессилие ожидания против активной веры в возвращение.','От тревоги к решимости.','Её голос становится знаком дороги домой.','Обращение к ветру с городской стены.',ARRAY['Фолк'],ARRAY['Тревога','Решимость'],'Средняя',ARRAY['Любовь','Возвращение'],'Фолк о женщине, которая превращает ожидание любимого в голос, ведущий его домой.','Жена зовёт ветер и прокладывает голосом дорогу домой.',129),
  ('Два места за столом','После унижения дочерей отец выбирает не месть, а публичную справедливость, чтобы вернуть им достоинство и свободу выбора.','От первого лица, отец.','Защита семьи против соблазна ответить насилием.','От гнева к решимости.','Дочери сами выбирают своё будущее.','Два пустых места за семейным столом.',ARRAY['Рок'],ARRAY['Решимость','Сила'],'Средняя',ARRAY['Семья','Сила'],'Рок о семье, которая добивается справедливости без мести и возвращает себе достоинство.','Отец защищает дочерей законом, а не местью, и возвращает им право выбора.',130)
)
INSERT INTO public.song_ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, is_published, sort_order)
SELECT title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, true, sort_order FROM ideas;

WITH sources (title, original_key, author_name, original_title, original_language, origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editor_note) AS (
  VALUES
  ('Не смотри в зеркало','alfred-tennyson|the-lady-of-shalott','Alfred Tennyson','The Lady of Shalott','English','United Kingdom',1832,'https://en.wikisource.org/wiki/Poems_(Tennyson,_1843)/Volume_1/The_Lady_of_Shalott','Автор умер в 1892 году; оригинал 1832 года, public domain.','["Loreena McKennitt — The Lady of Shalott"]','Изолированная женщина решается увидеть реальный мир, хотя знает о цене запрета.','Треснувшее зеркало','Современная адаптация не использует трагический финал и строки оригинала.'),
  ('Опоздал к рассвету','christina-rossetti|the-princes-progress','Christina Rossetti','The Prince’s Progress','English','United Kingdom',1866,'https://en.wikisource.org/wiki/Poems_(Rossetti,_1901)/The_Prince%27s_Progress','Автор умерла в 1894 году; оригинал XIX века, public domain.','[]','Невеста ждёт жениха, который слишком поздно проходит свой путь.','Закрывающаяся дверь','Берём цену промедления, без строк и религиозного финала.'),
  ('Держи, пока меняет','traditional-scottish|tam-lin','Traditional Scottish','Tam Lin','Scots','Scotland',1802,'https://en.wikisource.org/wiki/Tam_Lin','Традиционная баллада, опубликованные варианты XIX века; public domain.','["Fairport Convention — Tam Lin"]','Девушка спасает любимого, не отпуская его среди пугающих превращений.','Рука, которую нельзя разжать','Не используем строки и конкретные фольклорные формулы.'),
  ('Задача для двоих','traditional-scottish|the-elfin-knight','Traditional Scottish','The Elfin Knight','Scots','Scotland',1673,'https://en.wikisource.org/wiki/The_Elfin_Knight','Традиционная баллада; печатные варианты XVII века, public domain.','["Scarborough Fair — поздний вариант сюжета"]','Влюблённые обмениваются невыполнимыми заданиями.','Рубашка без швов','Адаптация сохраняет равный ответ на требования.'),
  ('Письмо с берега','traditional-scottish|sir-patrick-spens','Traditional Scottish','Sir Patrick Spens','Scots','Scotland',1765,'https://en.wikisource.org/wiki/Oxford_Book_of_English_Verse_1250-1900/Sir_Patrick_Spens','Традиционная баллада; public domain.','["Традиционные исполнения шотландских баллад"]','Капитана отправляют в опасное морское плавание вопреки его предчувствию.','Письмо с печатью','Адаптация заменяет катастрофический финал ответственным отказом.'),
  ('Луна проводит домой','william-wordsworth|the-idiot-boy','William Wordsworth','The Idiot Boy','English','United Kingdom',1798,'https://en.wikisource.org/wiki/Poems_(Wordsworth,_1815)/Volume_1/The_Idiot_Boy','Автор умер в 1850 году; оригинал 1798 года, public domain.','[]','Мать тревожится за сына в ночной дороге, а он возвращается своим путём.','Лунная дорога','Убираем устаревшую стигматизирующую лексику оригинала.'),
  ('Цена ответа','geoffrey-chaucer|the-wife-of-baths-tale','Geoffrey Chaucer','The Wife of Bath’s Tale','Middle English','England',1390,'https://en.wikisource.org/wiki/Chaucer%27s_Works_(ed._Skeat)_Vol._V/Wife_of_Bath','Автор умер в 1400 году; средневековый оригинал, public domain.','[]','Герой получает урок уважения к женской воле и достоинству.','Вопрос о выборе','Адаптация исключает исходное насилие и принуждение.'),
  ('Долг записан','robert-browning|the-pied-piper-of-hamelin','Robert Browning','The Pied Piper of Hamelin','English','United Kingdom',1842,'https://en.wikisource.org/wiki/The_Pied_Piper_of_Hamelin','Автор умер в 1889 году; оригинал XIX века, public domain.','["Многочисленные сценические и музыкальные адаптации"]','Город не платит человеку, выполнившему обещанную работу.','Неумолкающая мелодия','Детский трагический мотив не переносится.'),
  ('Вместо отца','unknown|ballad-of-mulan','Unknown','Ballad of Mulan','Chinese','China',550,'https://en.wikisource.org/wiki/Translation:Ballad_of_Mulan','Народная песнь VI века, public domain; используем оригинальный сюжет, не современный перевод.','["Многочисленные музыкально-сценические адаптации"]','Дочь идёт служить вместо отца и возвращается домой собой.','Доспех и зеркало','Независимый современный пересказ без строк.'),
  ('Не отпускай разговор','toru-dutt|savitri','Toru Dutt','Savitri','English','India',1882,'https://en.wikisource.org/wiki/Ancient_Ballads_and_Legends_of_Hindustan/Savitri','Автор умерла в 1877 году; поэма XIX века, public domain.','["Gustav Holst — Savitri"]','Савитри отстаивает жизнь мужа в разговоре с судьбой.','Ночной путь','Берём стойкость героини, не религиозные формулы.'),
  ('Счёт за свободу','nguyen-du|truyen-kieu','Nguyễn Du','Truyện Kiều','Vietnamese','Vietnam',1820,'https://vi.wikisource.org/wiki/Truyện_Kiều','Автор умер в 1820 году; Wikisource отмечает public domain worldwide.','["Вьетнамские театральные и музыкальные адаптации"]','Киều жертвует личным благополучием, чтобы спасти семью.','Струна в чужих руках','Работа только с оригиналом на вьетнамском и независимым смысловым разбором.'),
  ('Слова через пустыню','nizami-ganjavi|layla-and-majnun','Nizami Ganjavi','Layla and Majnun','Persian','Azerbaijan',1188,'https://en.wikisource.org/wiki/Author:Nizami','Автор умер около 1209 года; оригинал public domain worldwide.','["Uzeyir Hajibeyov — Leyli and Majnun","Gara Garayev — Leyli and Majnun"]','Влюблённых разлучают семейные запреты и общественное давление.','Сообщение через пустыню','Не использовать современные переводы.'),
  ('Имя без титула','alfred-tennyson|the-lord-of-burleigh','Alfred Tennyson','The Lord of Burleigh','English','United Kingdom',1842,'https://en.wikisource.org/wiki/Author:Alfred_Tennyson/Index_of_Titles','Автор умер в 1892 году; оригинал XIX века, public domain.','[]','Знатный мужчина скрывает происхождение от любимой.','Письмо с настоящей фамилией','Сюжет о доверии, не о классовой романтизации.'),
  ('Мы оба не сказали','john-greenleaf-whittier|maud-muller','John Greenleaf Whittier','Maud Muller','English','USA',1856,'https://en.wikisource.org/wiki/Maud_Muller','Автор умер в 1892 году; оригинал XIX века, public domain.','[]','Два человека не решаются сказать о взаимном чувстве из-за классовых ожиданий.','Развилка','Не переносить строки или готовые переводы.'),
  ('Семейный выезд','william-cowper|the-diverting-history-of-john-gilpin','William Cowper','The Diverting History of John Gilpin','English','United Kingdom',1782,'https://en.wikisource.org/wiki/The_Diverting_History_of_John_Gilpin','Автор умер в 1800 году; оригинал XVIII века, public domain.','["Традиционные декламационные и песенные версии"]','Семейная поездка превращается в комическую погоню.','Летящая шляпа','Тёплая ирония без копирования комических сцен.'),
  ('Камни у порога','william-wordsworth|michael','William Wordsworth','Michael','English','United Kingdom',1800,'https://en.wikisource.org/wiki/Michael_(Wordsworth)','Автор умер в 1850 году; оригинал XIX века, public domain.','[]','Отец жертвует всем ради сына, но не может выбрать за него жизнь.','Недостроенная стена','Второй источник Вордсворта, не подряд с другим автором.'),
  ('Дорога без карты','henry-wadsworth-longfellow|evangeline','Henry W. Longfellow','Evangeline','English','USA',1847,'https://en.wikisource.org/wiki/Evangeline','Автор умер в 1882 году; оригинал XIX века, public domain.','["Оперные и сценические адаптации"]','Катастрофа разлучает влюблённых на долгие годы.','Карта без маршрута','Не воспроизводить строки и финал оригинала.'),
  ('Берег, который выбрала','matthew-arnold|the-forsaken-merman','Matthew Arnold','The Forsaken Merman','English','United Kingdom',1849,'https://en.wikisource.org/wiki/The_Forsaken_Merman','Автор умер в 1888 году; оригинал XIX века, public domain.','[]','Мать выбирает мир людей, оставляя семью в другом мире.','Дети у воды','Адаптация уважает выбор героини, не делает её виноватой.'),
  ('Ветер услышит','unknown|the-tale-of-igors-campaign','Unknown','The Tale of Igor’s Campaign','Old East Slavic','Kyivan Rus',1185,'https://en.wikisource.org/wiki/The_Lay_of_the_Host_of_Igor','Анонимный памятник XII века, public domain.','["Alexander Borodin — Prince Igor"]','Жена пленённого князя обращается к стихиям, ожидая его возвращения.','Голос с городской стены','Сохраняем активный голос героини, не строки источника.'),
  ('Два места за столом','unknown|the-poem-of-the-cid','Unknown','The Poem of the Cid','Old Spanish','Spain',1207,'https://en.wikisource.org/wiki/The_Poem_of_the_Cid','Анонимный средневековый оригинал, public domain.','["Jules Massenet — Le Cid"]','Отец добивается справедливости после унижения дочерей.','Два пустых места','Исключаем насилие и делаем упор на закон и самостоятельность дочерей.')
)
INSERT INTO public.song_idea_sources (idea_id, original_key, author_name, original_title, original_language, origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editorial_status, editor_note)
SELECT i.id, s.original_key, s.author_name, s.original_title, s.original_language, s.origin_country, s.original_year, s.source_url, s.rights_check, s.music_adaptations::jsonb, s.source_synopsis, s.main_image, 'accepted', s.editor_note
FROM sources s JOIN public.song_ideas i ON i.title=s.title
ON CONFLICT (original_key) DO NOTHING;
